Translate the following MS C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
using namespace std;

int get_gcd(int a, int b) {
    if (b == 0) return a;
    return get_gcd(b, a % b);
}

int main() {
    int num_x, num_y, limit;
    cin >> num_x >> num_y >> limit;
    double target = (double)num_x / num_y;
    double min_difference = 1e9;
    int res_num = 0, res_den = 1;

    for (int i = 1; i <= limit; ++i) {
        int b = (long long)num_x * i / num_y;
        double candidates[] = {
            (double)b / i,
            (double)(abs(b - 1)) / i,
            (double)(b + 1) / i
        };
        int candidate_nums[] = {b, abs(b - 1), b + 1};

        for (int j = 0; j < 3; ++j) {
            double diff = fabs(target - candidates[j]);
            if (diff < min_difference) {
                min_difference = diff;
                res_num = candidate_nums[j];
                res_den = i;
            }
        }
    }

    if (fabs(1.0 - target) <= (fabs((double)res_num / res_den) - target) + 1e-9) {
        res_num = 1;
        res_den = 1;
    }

    int g = get_gcd(res_num, res_den);
    cout << res_num / g << "/" << res_den / g << endl;
    return 0;
}
